31	  <style>
32	    :root {
33	      color-scheme: light dark;
34	      --bg: #ffffff;
35	      --fg: #1a1a1a;
36	      --muted: #555;
37	      --accent: #2563eb;
38	      --border: #e5e7eb;
39	    }
40	
41	    @media (prefers-color-scheme: dark) {
42	      :root {
43	        --bg: #111214;
44	        --fg: #e8e8e8;
45	        --muted: #aaa;
46	        --accent: #60a5fa;
47	        --border: #2a2b2e;
48	      }
49	    }
50	
51	    :root[data-theme="light"] {
52	      color-scheme: light;
53	      --bg: #ffffff;
54	      --fg: #1a1a1a;
55	      --muted: #555;
56	      --accent: #2563eb;
57	      --border: #e5e7eb;
58	    }
59	
60	    :root[data-theme="dark"] {
61	      color-scheme: dark;
62	      --bg: #111214;
63	      --fg: #e8e8e8;
64	      --muted: #aaa;
65	      --accent: #60a5fa;
66	      --border: #2a2b2e;
67	    }
68	
69	    * {
70	      box-sizing: border-box;
71	    }
72	
73	    html {
74	      scroll-behavior: smooth;
75	    }
76	
77	    @media (prefers-reduced-motion: reduce) {
78	      html {
79	        scroll-behavior: auto;
80	      }
81	    }
82	
83	    ::selection {
84	      background: var(--accent);
85	      color: var(--bg);
86	    }
87	
88	    body {
89	      font-family: system-ui, -apple-system, sans-serif;
90	      max-width: 40rem;
91	      margin: 3rem auto;
92	      padding: 0 1rem;
93	      line-height: 1.6;
94	      color: var(--fg);
95	      background: var(--bg);
96	    }
97	
98	    @media (max-width: 30rem) {
99	      body {
100	        margin: 1.5rem auto;
101	      }
102	    }
103	
104	    h1 {
105	      font-size: clamp(1.75rem, 5vw, 2.5rem);
106	      margin-bottom: 0.5rem;
107	    }
108	
109	    p {
110	      color: var(--muted);
111	      max-width: 34rem;
112	    }
113	
114	    a {
115	      color: var(--accent);
116	      transition: opacity 0.15s ease;
117	    }
118	
119	    a:hover {
120	      opacity: 0.8;
121	    }
122	
123	    a:focus-visible,
124	    button:focus-visible {
125	      outline: 2px solid var(--accent);
126	      outline-offset: 2px;
127	    }
128	
129	    .skip-link {
130	      position: absolute;
131	      left: -9999px;
132	      top: 0;
133	      background: var(--accent);
134	      color: var(--bg);
135	      padding: 0.5rem 1rem;
136	      border-radius: 0.25rem;
137	      z-index: 10;
138	    }
139	
140	    .skip-link:focus {
141	      left: 1rem;
142	      top: 1rem;
143	    }
144	
145	    main:focus {
146	      outline: none;
147	    }
148	
149	    nav {
150	      display: flex;
151	      align-items: center;
152	      gap: 1rem;
153	      margin-bottom: 2rem;
154	    }
155	
156	    nav ul {
157	      display: flex;
158	      flex-wrap: wrap;
159	      gap: 1rem;
160	      list-style: none;
161	      padding: 0;
162	      margin: 0;
163	    }
164	
165	    nav a {
166	      text-decoration: none;
167	      font-weight: 500;
168	      opacity: 1;
169	    }
170	
171	    nav a:hover {
172	      text-decoration: underline;
173	    }
174	
175	    nav a[aria-current="page"] {
176	      text-decoration: underline;
177	      color: var(--fg);
178	      font-weight: 700;
179	    }
180	
181	    .theme-toggle {
182	      margin-left: auto;
183	      background: none;
184	      border: 1px solid var(--border);
185	      color: var(--fg);
186	      border-radius: 0.375rem;
187	      padding: 0.25rem 0.6rem;
188	      font: inherit;
189	      font-size: 0.875rem;
190	      cursor: pointer;
191	    }
192	
193	    .theme-toggle:hover {
194	      border-color: var(--accent);
195	    }
196	
197	    h2 {
198	      margin-top: 2rem;
199	      margin-bottom: 0.5rem;
200	    }
201	
202	    section + section {
203	      margin-top: 1.5rem;
204	    }
205	
206	    section {
207	      scroll-margin-top: 1.5rem;
208	    }
209	
210	    footer {
211	      margin-top: 3rem;
212	      padding-top: 1.5rem;
213	      border-top: 1px solid var(--border);
214	      font-size: 0.875rem;
215	      color: var(--muted);
216	    }
217	
218	    @media print {
219	      .skip-link,
220	      nav {
221	        display: none;
222	      }
223	    }
224	  </style>
225	  <script>
226	    (function () {
227	      try {
228	        const stored = localStorage.getItem('theme');
229	        if (stored === 'light' || stored === 'dark') {
230	          document.documentElement.dataset.theme = stored;
231	        }
232	      } catch (e) {
233	        // localStorage may be unavailable (e.g. private browsing); fall back to OS preference.
234	      }
235	    })();
236	  </script>
237	</head>
238	<body>
239	  <a class="skip-link" href="#main">Skip to content</a>
240	  <header>
241	    <nav aria-label="Primary">
242	      <ul>
243	        <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
244	        <li><a href="#about" data-nav-link>About</a></li>
245	        <li><a href="#contact" data-nav-link>Contact</a></li>
246	      </ul>
247	      <button type="button" class="theme-toggle" id="theme-toggle" aria-label="Toggle color theme" aria-pressed="false"><span aria-hidden="true">🌙</span></button>
248	    </nav>
249	  </header>
250	  <main id="main" tabindex="-1">
251	    <section id="home" aria-labelledby="home-heading">
252	      <h1 id="home-heading">My Page</h1>
253	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
254	    </section>
255	
256	    <section id="about" aria-labelledby="about-heading">
257	      <h2 id="about-heading">About</h2>
258	      <p>Add a short description of what this page or project is about here.</p>
259	    </section>
260	
261	    <section id="contact" aria-labelledby="contact-heading">
262	      <h2 id="contact-heading">Contact</h2>
263	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
264	    </section>
265	  </main>
266	  <footer>
267	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
268	  </footer>
269	  <script>
270	    const yearEl = document.getElementById('year');
271	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
272	
273	    const themeToggle = document.getElementById('theme-toggle');
274	    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
275	
276	    const currentTheme = () =>
277	      document.documentElement.dataset.theme || (prefersDark.matches ? 'dark' : 'light');
278	
279	    const updateToggleLabel = () => {
280	      const isDark = currentTheme() === 'dark';
281	      themeToggle.querySelector('span').textContent = isDark ? '☀️' : '🌙';
282	      themeToggle.setAttribute('aria-pressed', String(isDark));
283	      themeToggle.setAttribute('aria-label', isDark ? 'Switch to light theme' : 'Switch to dark theme');
284	    };
285	
286	    updateToggleLabel();
287	
288	    const themeColorMetas = [
289	      document.getElementById('theme-color-light'),
290	      document.getElementById('theme-color-dark'),
291	    ].filter(Boolean);
292	
293	    const syncThemeColorMeta = () => {
294	      const color = currentTheme() === 'dark' ? '#111214' : '#ffffff';
295	      themeColorMetas.forEach(meta => meta.setAttribute('content', color));
296	    };
297	
298	    syncThemeColorMeta();
299	
300	    themeToggle.addEventListener('click', () => {
301	      const next = currentTheme() === 'dark' ? 'light' : 'dark';
302	      document.documentElement.dataset.theme = next;
303	      try {
304	        localStorage.setItem('theme', next);
305	      } catch (e) {
306	        // localStorage may be unavailable; theme still applies for this session.
307	      }
308	      updateToggleLabel();
309	      syncThemeColorMeta();
310	    });
311	
312	    prefersDark.addEventListener('change', () => {
313	      if (!document.documentElement.dataset.theme) updateToggleLabel();
314	    });
315	
316	    const navLinks = document.querySelectorAll('[data-nav-link]');
317	    const sections = [...navLinks]
318	      .map(link => document.querySelector(link.getAttribute('href')))
319	      .filter(Boolean);
320	
321	    const setActive = (id) => {
322	      navLinks.forEach(link => {
323	        if (link.getAttribute('href') === `#${id}`) {
324	          link.setAttribute('aria-current', 'page');
325	        } else {
326	          link.removeAttribute('aria-current');
327	        }
328	      });
329	    };
330	
331	    setActive(sections[0]?.id);
332	
333	    navLinks.forEach(link => {
334	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
335	    });
336	
337	    if ('IntersectionObserver' in window) {
338	      const observer = new IntersectionObserver((entries) => {
339	        const visible = entries
340	          .filter(entry => entry.isIntersecting)
341	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
342	        if (visible) setActive(visible.target.id);
343	      }, { rootMargin: '-40% 0px -50% 0px' });
344	      sections.forEach(section => section && observer.observe(section));
345	    }
346	  </script>
347	</body>
348	</html>
